CREATE TABLE IF NOT EXISTS cia_liquidaciones.encargados_cc (
  id                   SERIAL PRIMARY KEY,
  llave                VARCHAR,
  sociedad             VARCHAR,
  centro_coto          VARCHAR,
  administrativo       VARCHAR,
  correo               VARCHAR,
  ver_planta           VARCHAR,
  administrador        VARCHAR,
  correo_administrador VARCHAR,
  visitador            VARCHAR,
  correo_visitador     VARCHAR,
  gerente              VARCHAR,
  correo_gerente       VARCHAR,
  correo_ggo           VARCHAR,
  division             VARCHAR,
  actualizado_por      VARCHAR(255),
  updated_at           TIMESTAMPTZ NOT NULL DEFAULT now()
);

