-- Quien aparece como encargado, visitador o GGO y aún no está en usuarios entra con los valores
-- por defecto (miembro, jefatura, sin rol en los libros), que son los mismos que tiene hoy sin
-- fila: no cambia lo que ve, pero así aparece en Configuración › Usuarios y roles.
INSERT INTO cia_liquidaciones.usuarios (correo)
SELECT DISTINCT lower(trim(x)) FROM (
  SELECT correo AS x FROM cia_liquidaciones.encargados_cc
  UNION ALL SELECT visitador FROM cia_liquidaciones.encargados_cc
  UNION ALL SELECT unnest(string_to_array(correo_ggo, ',')) FROM cia_liquidaciones.encargados_cc
) c
WHERE lower(trim(x)) ~ '^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$'
ON CONFLICT (correo) DO NOTHING;

COMMIT;
